@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=DM+Sans:wght@400;500;600;700&family=Playfair+Display:ital,wght@0,500;0,600;0,700;1,500;1,600&display=swap');
:root{--bg:#08130f;--panel:#0c1b15;--line:rgba(193,225,199,.12);--text:#e5efdf;--muted:#84988b;--green:#a4e785;--mint:#66d7a4;--gold:#e5c986;--mono:'DM Mono',monospace;--sans:'DM Sans',sans-serif;--serif:'Playfair Display',serif}*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;background:var(--bg);color:var(--text);font-family:var(--sans);overflow:hidden}body{background:radial-gradient(ellipse at 53% 45%,#10271a 0,#091710 49%,#06100c 100%)}button{font:inherit;color:inherit;cursor:pointer}.app-shell{max-width:1600px;margin:auto;height:100dvh;display:flex;flex-direction:column;padding:0 40px}.topbar{height:74px;min-height:74px;display:flex;align-items:center;border-bottom:1px solid var(--line);position:relative;z-index:2}.brand{display:flex;align-items:center;gap:10px;color:#e5efdf;text-decoration:none;font:600 19px var(--serif);letter-spacing:-.4px}.brand-mark{color:var(--green);font:20px var(--sans);display:grid;place-items:center;width:27px;height:27px;border:1px solid #547953;border-radius:50%;box-shadow:0 0 16px #74cb6333}.brand-period{color:var(--green)}.season-tag{position:absolute;left:50%;transform:translateX(-50%);font:10px var(--mono);letter-spacing:1.6px;color:#91a99a}.season-dot{display:inline-block;width:6px;height:6px;background:var(--green);border-radius:50%;margin:0 10px 1px 0;box-shadow:0 0 9px var(--green)}.top-actions{margin-left:auto;display:flex;gap:9px}.icon-btn{height:34px;width:34px;background:#14251c;border:1px solid var(--line);border-radius:50%;color:#b4c9b8;font-size:15px;transition:.2s}.icon-btn:hover{border-color:var(--green);color:var(--green)}.game-layout{display:grid;grid-template-columns:260px minmax(400px,1fr) 268px;gap:26px;flex:1;min-height:0;padding:27px 0 24px}.left-rail,.detail-panel{min-width:0}.left-rail{display:flex;flex-direction:column;padding:25px 0 0}.eyebrow{font:10px var(--mono);letter-spacing:1.35px;color:#91ad96}.left-rail h1{font:500 40px/1.07 var(--serif);letter-spacing:-1.3px;margin:17px 0 13px}.left-rail h1 em,.help-card h2 em{font-weight:500;color:var(--green)}.intro{color:#91a398;font-size:13px;line-height:1.65;margin:0 8px 25px 0;max-width:240px}.resource-card{padding:16px 16px 13px;background:linear-gradient(145deg,#13271c,#0d1b14);border:1px solid #34503966;border-radius:10px;box-shadow:0 12px 30px #0002}.resource-head{font:9px var(--mono);letter-spacing:1.15px;color:#a8bca9;display:flex;align-items:center;gap:8px}.resource-icon{color:var(--green);font-size:14px}.live-pill{margin-left:auto;font-size:8px;color:#9bd889;letter-spacing:.8px}.live-pill i,.save-status i{display:inline-block;width:5px;height:5px;border-radius:100%;background:#a2e57d;margin:0 5px 1px 0;box-shadow:0 0 7px #a2e57d}.resource-value{font:500 39px/1.2 var(--serif);letter-spacing:-1px;margin-top:8px;color:#e4eedf}.resource-foot{display:flex;justify-content:space-between;font-size:11px;color:#829589;margin-top:1px}.resource-foot strong{font:11px var(--mono);color:#a6e289}.resource-rule{height:1px;background:var(--line);margin:14px 0 10px}.resource-row{font-size:10px;color:#83988a;display:flex;justify-content:space-between;margin-top:8px}.resource-row strong{font:10px var(--mono);color:#c3d6c3}.tap-button{position:relative;margin-top:17px;width:100%;height:51px;border:1px solid #9bdd7080;background:linear-gradient(110deg,#3b793b,#589448);border-radius:7px;box-shadow:0 6px 22px #75c75322,inset 0 1px #ffffff20;display:flex;align-items:center;justify-content:center;gap:10px;font-size:12px;font-weight:600;transition:transform .15s,filter .15s}.tap-button:hover{filter:brightness(1.13);transform:translateY(-1px)}.tap-button:active{transform:scale(.97)}.tap-spark{font-size:19px;color:#e8f7cf}.tap-button kbd{position:absolute;right:10px;top:17px;color:#d0e7be99;font:8px var(--mono);border:1px solid #b5d39a55;border-radius:3px;padding:3px 4px}.tap-hint{text-align:center;color:#869a8d;font-size:10px;margin-top:9px}.tap-hint b{font:10px var(--mono);color:#b1d69b}.ascend-button{margin-top:19px;min