;overflow:hidden}.art-ring{position:absolute;width:82px;height:82px;border:1px solid #94d58058;border-radius:50%;box-shadow:0 0 27px #9bdd3724,inset 0 0 20px #83cb3420}.art-ring:before,.art-ring:after{content:'';position:absolute;inset:11px;border:1px dashed #b6d9824c;border-radius:50%;transform:rotateX(63deg) rotateZ(20deg)}.art-ring:after{transform:rotateX(63deg) rotateZ(-50deg)}.art-symbol{position:relative;color:#c5ed97;font-size:33px;text-shadow:0 0 24px #a6e98b;animation:float 3s ease-in-out infinite}.art-caption{position:absolute;bottom:11px;font:7px var(--mono);letter-spacing:1.4px;color:#769178}.detail-effect{display:flex;flex-direction:column;gap:6px;padding:0 1px}.detail-effect>span{font:8px var(--mono);letter-spacing:1px;color:#718b77}.detail-effect strong{font-size:11px;line-height:1.45;font-weight:500;color:#d0dfcc;min-height:31px}.buy-button{width:100%;height:41px;flex:none;margin-top:13px;background:#a2dc7d;border:1px solid #b9ef98;border-radius:5px;color:#132412;font:700 10px var(--mono);letter-spacing:.7px;display:flex;justify-content:center;align-items:center;gap:9px;transition:.15s}.buy-button:not(:disabled):hover{filter:brightness(1.1);transform:translateY(-1px);box-shadow:0 4px 16px #9ad97f35}.buy-button:disabled{background:#1b2c20;border-color:#344b38;color:#718575;cursor:default}.buy-cost{font:9px var(--mono);opacity:.8}.detail-foot{font-size:9px;line-height:1.4;color:#7e9383;text-align:center;margin-top:8px;min-height:13px}.mini-progress{display:flex;align-items:center;gap:8px;margin-top:auto;padding-top:13px;color:#829485;font:8px var(--mono);letter-spacing:.4px}.progress-track{height:3px;background:#263a2b;flex:1;border-radius:4px;overflow:hidden}.progress-track i{height:100%;display:block;background:linear-gradient(90deg,#85cf6f,#c2e891);width:1%;transition:width .3s}.mini-progress strong{color:#c5d6c1;font-weight:400}.ascension-info{border-top:1px solid var(--line);margin-top:13px;padding-top:12px;display:flex;align-items:center;gap:9px;font-size:10px;color:#d4cb9d}.ascension-info>span{font-size:18px;color:#ebd185}.ascension-info b{font:11px var(--mono);color:#f0d892}.ascension-info small{display:block;color:#809082;font-size:9px;margin-top:2px}footer{height:37px;min-height:37px;border-top:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;color:#63786a;font:8px var(--mono);letter-spacing:.8px}.footer-center{font:italic 11px var(--serif);letter-spacing:0;color:#849687}.mobile-resource{display:none}.toast{position:fixed;z-index:9;bottom:25px;left:50%;transform:translate(-50%,20px);padding:10px 16px;background:#213b27;border:1px solid #769e60;border-radius:6px;color:#d8edc6;font:11px var(--sans);box-shadow:0 8px 30px #0008;opacity:0;pointer-events:none;transition:.25s}.toast.show{opacity:1;transform:translate(-50%,0)}.modal-backdrop{position:fixed;inset:0;background:#030a07c9;z-index:12;display:grid;place-items:center;padding:20px;backdrop-filter:blur(8px)}.modal-backdrop[hidden]{display:none}.help-card{width:min(440px,100%);position:relative;background:linear-gradient(145deg,#173021,#0b1912);border:1px solid #8dac773d;border-radius:12px;padding:30px 32px;box-shadow:0 25px 100px #0009}.modal-close{position:absolute;right:15px;top:12px;background:none;border:0;color:#93a795;font-size:23px}.help-card h2{font:500 31px/1.18 var(--serif);margin:16px 0 13px}.help-card>p{font-size:12px;line-height:1.7;color:#9eafa0}.help-card>p b{color:#e4cc86}.help-types{display:grid;grid-template-columns:1fr 1fr;gap:9px;padding:12px;background:#102117;border:1px solid var(--line);border-radius:6px;font-size:10px;color:#c0d0bb}.help-types span:first-letter{color:#a8df83}.help-card .buy-button{margin-top:18px}@keyframes float{50%{transform:translateY(-4px)}}
