:2;grid-row:6;margin-top:5px;font-size:8px}.mini-progress{grid-column:1/-1;margin-top:11px;padding-top:9px}.ascension-info{grid-column:1/-1;margin-top:9px;padding-top:8px}.rail-bottom{font-size:7px}.reset-link{font-size:8px}footer{margin-top:auto;height:31px;min-height:31px;font-size:7px}.footer-center{font-size:10px}.mobile-resource{display:none}}
