const $=id=>document.getElementById(id);
const COLORS={tap:0xb8ed82,upgrade:0x75dba3,buyer:0xf0cd7a,auto:0x67d9c8,speed:0x8db7f4,rebirth:0xe6a8d7,root:0xd9f4ad};
const TYPES={tap:{name:'TAP MULTIPLIER',short:'Tap',symbol:'✧'},upgrade:{name:'UPGRADE POWER',short:'Upgrade',symbol:'◉'},buyer:{name:'AUTO BUYER',short:'Auto buy',symbol:'↗'},auto:{name:'AUTO TAPS',short:'Auto taps',symbol:'✦'},speed:{name:'TIME WARP',short:'Speed',symbol:'⌁'},rebirth:{name:'BLOOM SEED',short:'Bloom',symbol:'✿'}};
const colorCss={tap:'#b8ed82',upgrade:'#75dba3',buyer:'#f0cd7a',auto:'#67d9c8',speed:'#8db7f4',rebirth:'#e6a8d7'};
const categories=['tap','upgrade','auto','buyer','speed','tap','upgrade','auto','rebirth','tap','speed','buyer','upgrade','auto','tap','rebirth','speed','upgrade','buyer','tap','auto','speed','rebirth','upgrade'];
const nodes=[{id:0,depth:0,angle:0,parent:-1,type:'root',cost:0,name:'The First Seed',desc:'Every great forest begins somewhere. Tap the seed to help it wake.',effect:'Your journey starts here.'}];
let id=1;const widths=[6,12,18,24];
for(let d=1;d<=4;d++){for(let j=0;j<widths[d-1];j++){const angle=(j/widths[d-1])*Math.PI*2-Math.PI/2+(d%2)*.1;let p;if(d===1)p=0;else p=1+Math.round((((angle+Math.PI/2-(d%2)*.1+Math.PI*4)%(Math.PI*2))/(Math.PI*2))*widths[d-2])%widths[d-2]+widths.slice(0,d-2).reduce((a,b)=>a+b,0);const type=categories[(id-1)%categories.length];const scale=[1,1,1.22,1.5,1.82][d];const cost=Math.floor((d===1?8:18)*Math.pow(2.15,d-1)*(1+(j%3)*.17));const data={tap:['Gentle Touch','A little more love goes a long way.','Tap power +1'],upgrade:['Rich Soil','Every upgrade grows a little stronger.','Upgrade effects +20%'],auto:['Firefly Chorus','A few tiny helpers gather dewdrops for you.','Auto taps +0.6 / sec'],buyer:['Helpful Sprout','A growing sprout buys the next available branch.','Automatically buy affordable nodes'],speed:['Time Blossom','The whole little world begins to hurry.','Simulation speed ×1.35'],rebirth:['Blooming Promise','A permanent spark that makes every new beginning brighter.','Gain 1 bloom essence · permanent +25%']}[type];nodes.push({id:id++,depth:d,angle,parent:p,type,cost:Math.floor(cost/scale),name:data[0],desc:data[1],effect:data[2]});}}
let state={dew:0,lifetime:0,essence:0,owned:[0],selected:0,totalTaps:0,lastTime:Date.now(),speed:1};
function load(){try{const saved=JSON.parse(localStorage.getItem('verdant-save'));if(saved){state={...state,...saved};state.owned=[...new Set([0,...(saved.owned||[]).filter(i=>i>0&&i<nodes.length)])];const offline=Math.min(8*3600,Math.max(0,(Date.now()-(saved.lastTime||Date.now()))/1000));const rate=calcRate();state.dew+=rate*offline;state.lifetime+=rate*offline;}}catch(e){}}
function save(){state.lastTime=Date.now();try{localStorage.setItem('verdant-save',JSON.stringify(state));}catch(e){}}
load();
const isOwned=n=>state.owned.includes(n.id),getNode=id=>nodes[id];
function typeCount(type){return state.owned.filter(i=>nodes[i]?.type===type).length;}
function multipliers(){return{tap:(1+typeCount('tap'))*(1+state.essence*.25),upgrade:1+typeCount('upgrade')*.2,bloom:1+state.essence*.25};}
function calcRate(){const m=multipliers();return(typeCount('auto')*.6*state.speed+typeCount('buyer')*.15)*m.upgrade*m.bloom;}
function costOf(n){return Math.floor(n.cost/Math.pow(1+typeCount('upgrade')*.08,1));}
function canBuy(n){return n&&n.id!==0&&!isOwned(n)&&isOwned(getNode(n.parent))&&state.dew>=costOf(n);}
function fmt(n){if(!isFinite(n))return'∞';if(n<1000)return Math.floor(n).toLocaleString();const units=['K','M','B','T','Qa','Qi','Sx','Sp'];let i=-1;while(n>=1000&&i<units.length-1){n/=1000;i++;}return n.toFixed(n<10?2:1)+units[i];}
function notify(msg){const t=$('toast');t.textContent=msg;t.classList.add('show');clearTimeout(notify.timer);notify.timer=setTimeout(()=>t.classList.remove('show'),2100);}
function renderUI(){const n=getNode(state.selected)||nodes[0],owned=isOwned(n),available=n.id!==0&&isOwned(getNode(n.parent)),m=multipliers(),count=state.owned.length;
$('dewCount').textContent=fmt(state.dew);$('rateCount').textContent='+'+fmt(calcRate());$('lifetimeCount').textContent=fmt(state.lifetime);$('speedCount').textContent=state.speed.toFixed(state.speed%1?2:0)+'×';$('tapPower').textContent=fmt(m.tap);$('mobileDew').textContent=fmt(state.dew);$('mobileRate').textContent='+'+fmt(calcRate())+' / sec';$('nodeTotal').textContent=String(count).padStart(2,'0')+' / '+nodes.length+' GROWN';$('progressText').textContent=count+' / '+nodes.length;$('progressFill').style.width=(count/nodes.length*100)+'%';$('essenceCount').textContent=state.essence;
